    /**
     * @param args the command line arguments
     */
    public static void main(String args[]) {
       Generador f=new Generador();
       f.setSize(800,450);
        f.setTitle("Tunel");
        
        int numHilos = 10;
        
        Semaphore semCoche = new Semaphore(2);
        Semaphore semTotal = new Semaphore(3);
        Semaphore semFurgo = new Semaphore(2);
        
        
        Random r = new Random(System.currentTimeMillis());
        Thread[] hilos = new Thread[numHilos];    
    
        for(int i=0;i<numHilos;i++){
            if(r.nextInt(100)<50){
                hilos[i]=new Coche(i, semCoche, semTotal);
            }else{
                hilos[i]=new Thread(new Furgo(i,semFurgo, semTotal));
            }
            hilos[i].start();
            try {
                Thread.sleep(r.nextInt(1000, 2001));   //llegan cada 1-2 segundos
            } catch (InterruptedException ex) {
            }
        }
       for (int i = 0; i < numHilos; i++) {
            try {
                hilos[i].join();
            } catch (InterruptedException ex) {
            }
        }

        System.out.println("Todos han terminado");
        try {
            Thread.sleep(3000);//espero 3 segundos para que se vea el estado final
        } catch (InterruptedException ex) {
        }
        System.exit(0);
    
    }


